// background.js

chrome.action.onClicked.addListener((tab) => {
  // Check if the active tab is allowed to be captured (usually fine for web pages)
  chrome.tabs.captureVisibleTab(null, { format: 'png' }, (dataUrl) => {
    if (chrome.runtime.lastError) {
      console.error(chrome.runtime.lastError);
      return;
    }

    // Define the filename with a timestamp to ensure uniqueness
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const filename = `screenshot_${timestamp}.png`;

    // Create a new download entry
    chrome.downloads.download({
      url: dataUrl,
      filename: filename,
      saveAs: false // Set to true if you want the "Save As" dialog to appear
    });
  });
});
```

